# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"
require_relative "../../support/timekeeping/fake_timekeeping"

RSpec.describe Timekeeping::Gateway, committed_data: true do
  it "makes an agent destroy wait for a forwarded agent create held inside its call, then detaches the entry that create committed" do
    base_url = "http://timekeeping.test"
    company = create(:company)
    project = create(:project, billable: true, client: create(:client, company:))
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :employee, company
    agent = create(:agent, company:, user:, default_project: project)
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: user.id, company_id: company.id, role: "employee")
    fake.register_project(id: project.id, company_id: company.id)
    fake.register_agent(id: agent.id, company_id: company.id, user_id: user.id)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = 2

    entered = Queue.new
    release = Queue.new
    # Holds the create inside its forwarded call, after the gateway has taken
    # the ownership and agent share locks, so the destroy's ordering is forced.
    paused_client = Class.new(Timekeeping::EntryWriteClient) do
      define_method(:create_entry) do |**arguments|
        entered << true
        release.pop(timeout: 10)
        super(**arguments)
      end
    end
    context = Timekeeping::WriteContext.new(company:, actor: user, actor_kind: "agent",
                                            request_id: "req-agent-race-create", agent:)
    creator_pids = Queue.new
    destroyer_pids = Queue.new
    creator = destroyer = created = nil

    with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, base_url) do
      with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
        creator = committed_data_thread(creator_pids) do
          described_class.new(context:, write_client: paused_client.new(base_url:)).create(
            user:, project:, attributes: { duration: 30, work_date: Date.current, note: "race create",
                                           source: "automation", agent_id: agent.id }
          )
        end
        expect(entered.pop(timeout: 5)).to be(true)

        destroyer = committed_data_thread(destroyer_pids) { Agent.find(agent.id).destroy! }
        begin
          blocked = blocked_by?(destroyer_pids.pop(timeout: 5), creator_pids.pop(timeout: 5))
        ensure
          release << true
        end

        # "A forwarded agent create racing an agent destroy, which detaches through `Timekeeping::Gateway#detach_agent_entries`, either finishes before the detach and is detached, or is refused. It never leaves an entry naming a deleted agent."
        expect(blocked).to be(true), "the agent destroy did not wait for the create holding the agent lock"
        created = creator.join(10).value
        destroyer.join(10)
      end
    end

    create_request = fake.requests.find { |request| request[:method] == "POST" && request[:path].end_with?("/entries") }
    expect(create_request[:body]["agent_id"]).to eq(agent.id)
    expect(Agent.exists?(agent.id)).to be(false)
    expect(fake.stored_entry(created.id)["agent_id"]).to be_nil
  ensure
    release&.push(true)
    [creator, destroyer].compact.each { |thread| thread.join(5) }
  end
end

RSpec.describe Timekeeping::Gateway, committed_data: true do
  it "refuses a forwarded agent create that waited on an agent destroy, and forwards nothing to Timekeeping" do
    base_url = "http://timekeeping.test"
    company = create(:company)
    project = create(:project, billable: true, client: create(:client, company:))
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :employee, company
    agent = create(:agent, company:, user:, default_project: project)
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: user.id, company_id: company.id, role: "employee")
    fake.register_project(id: project.id, company_id: company.id)
    fake.register_agent(id: agent.id, company_id: company.id, user_id: user.id)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = 2

    destroyed = Queue.new
    release = Queue.new
    holder_pids = Queue.new
    creator_pids = Queue.new
    context = Timekeeping::WriteContext.new(company:, actor: user, actor_kind: "agent",
                                            request_id: "req-agent-race-refused", agent:)
    holder = creator = nil
    outcome = nil

    with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, base_url) do
      with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
        # The destroy runs first and keeps its transaction, and so its agent
        # row lock, open until released.
        holder = committed_data_thread(holder_pids) do
          ActiveRecord::Base.transaction do
            Agent.find(agent.id).destroy!
            destroyed << true
            release.pop(timeout: 10)
          end
        end
        expect(destroyed.pop(timeout: 10)).to be(true)

        creator = committed_data_thread(creator_pids) do
          described_class.new(context:).create(
            user:, project:, attributes: { duration: 30, work_date: Date.current, note: "race refused",
                                           source: "automation", agent_id: agent.id }
          )
          :created
        rescue ActiveRecord::RecordInvalid
          :refused
        end

        begin
          blocked = blocked_by?(creator_pids.pop(timeout: 5), holder_pids.pop(timeout: 5))
        ensure
          release << true
        end
        holder.join(10)
        outcome = creator.join(10).value

        # "The lock order is always the ownership row first, then the agent row."
        expect(blocked).to be(true), "the create never waited on the agent row the destroy holds"
      end
    end

    # "A destroyed agent refuses the write with the same 422 the model gives."
    expect(outcome).to eq(:refused)
    # "It never leaves an entry naming a deleted agent."
    expect(fake.requests.select { |request| request[:method] == "POST" && request[:path].end_with?("/entries") }).to be_empty
    expect(fake.outbox.map { |row| row["entry"]["agent_id"] }).not_to include(agent.id)
  ensure
    release&.push(true)
    [holder, creator].compact.each { |thread| thread.join(5) }
  end
end
